// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // NAIVE2: sub-stepped movement + group resolution, but paddle left untouched.
  const norm = Math.hypot(ball.vx, ball.vy);
  const n = Math.max(1, Math.ceil((norm * dt) / 8));
  const h = dt / n;
  for (let i = 0; i < n; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle (OLD behavior, untouched)
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks: group resolution (one flip per axis, push-out, corner)
    const hit = state.bricks.filter((b) => b.alive && collides(ball, b));
    if (hit.length > 0) {
      for (const brick of hit) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
      let penX = 0;
      let penY = 0;
      for (const brick of hit) {
        penX = Math.max(penX, Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x));
        penY = Math.max(penY, Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y));
      }
      const corner = penX === penY;
      const flipX = corner || penX < penY;
      const flipY = corner || penY < penX;
      if (flipX) ball.vx = -ball.vx;
      if (flipY) ball.vy = -ball.vy;
      if (flipX) ball.x = ball.vx < 0 ? Math.min(...hit.map((b) => b.x)) - ball.r : Math.max(...hit.map((b) => b.x + b.w)) + ball.r;
      if (flipY) ball.y = ball.vy < 0 ? Math.min(...hit.map((b) => b.y)) - ball.r : Math.max(...hit.map((b) => b.y + b.h)) + ball.r;
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

