      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks: group resolution (one flip per axis, push-out, corner)
    const hit = state.bricks.filter((b) => b.alive && collides(ball, b));
    if (hit.length > 0) {
      for (const brick of hit) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);
      }
      let penX = 0;
      let penY = 0;
      for (const brick of hit) {
        penX = Math.max(penX, Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x));
        penY = Math.max(penY, Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y));
      }
      const corner = penX === penY;
      const flipX = corner || penX < penY;
      const flipY = corner || penY < penX;
      if (flipX) ball.vx = -ball.vx;
      if (flipY) ball.vy = -ball.vy;
      if (flipX) ball.x = ball.vx < 0 ? Math.min(...hit.map((b) => b.x)) - ball.r : Math.max(...hit.map((b) => b.x + b.w)) + ball.r;
