// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. The movement is sub-divided so that a
// single sub-step can never jump over a brick's contact zone (tunneling): a
// sub-step is at most MAX_SUB_STEP pixels.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  const steps = Math.max(1, Math.ceil((norm * dt) / MAX_SUB_STEP));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    moveBall(state, h);
    if (state.ball.y - state.ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

// One sub-step: move the ball, bounce off walls, ceiling, paddle and bricks.
function moveBall(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.x + ball.r > paddle.x &&
    ball.x - ball.r < paddle.x + paddle.w &&
    ball.y + ball.r >= paddle.y &&
    ball.y - ball.r <= paddle.y + paddle.h
  ) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit, the speed is
    // conserved (norm == ballSpeed(level)) and a center hit still gets a
    // playable horizontal component.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const speed = ballSpeed(state.level);
    const dir = hit >= 0 ? RIGHT : LEFT;
    const mag = Math.max(Math.abs(0.6 * hit), MIN_VX_FRAC) * speed;
    ball.vx = dir * mag;
    ball.vy = -Math.sqrt(Math.max(speed * speed - mag * mag, 0));
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  resolveBrickCollisions(state);
}

