    ball.y = ball.vy < 0 ? Math.min(...hit.map((b) => b.y)) - ball.r : Math.max(...hit.map((b) => b.y + b.h)) + ball.r;
  }
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. The movement is sub-divided so that a
// single sub-step can never jump over an obstacle (tunneling): each sub-step
// is at most MAX_SUB_STEP pixels.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  const steps = Math.max(1, Math.ceil((norm * dt) / MAX_SUB_STEP));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    moveBall(state, h);
    if (state.ball.y - state.ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

// One sub-step: move the ball, bounce off walls, ceiling, paddle and bricks.
function moveBall(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — box overlap test: the ball always exits through the top, even
  // when the mouse teleports the paddle onto it (a point test would miss it).
  if (
    ball.vy > 0 &&
    ball.x + ball.r > paddle.x &&
    ball.x - ball.r < paddle.x + paddle.w &&
    ball.y + ball.r >= paddle.y &&
    ball.y - ball.r <= paddle.y + paddle.h
  ) {
    ball.y = paddle.y - ball.r;
    // The rebound angle depends on where the paddle was hit; a center hit
    // still gets a playable horizontal component (no dead angle), and the
    // speed is conserved: the norm stays ballSpeed(level).
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const speed = ballSpeed(state.level);
    const dir = hit >= 0 ? RIGHT : LEFT;
    const mag = Math.max(Math.abs(0.6 * hit), MIN_VX_FRAC) * speed;
    ball.vx = dir * mag;
    ball.vy = -Math.sqrt(Math.max(speed * speed - mag * mag, 0));
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  resolveBrickCollisions(state);
}

